    (0 < n -> forall x : word, fD <= U x < lD -> mem0 x = Some (Z_to_bv 8 0)) -> (0 < n -> mem0 (Z_to_bv 64 lD) = Some (Z_to_bv 8 kD)) ->
    (kD = 0 \/ (pd + n - 1) mod 8 < kD <= 7) ->
